// План specs/addresses.md 3.4 (кейс AD-13). Pre-Prod, preprod-ttp (TTP Test Locks), десктоп, EN. Лид не сохраняется. Зависит от Google Places.
import { test, expect } from '../../fixtures';
import { ROLE, addressInput, city, openNewLead, region, typeAndPickSuggestion, zip } from './lead-address-helpers';

test.describe('Адрес: City из подсказки — город, не район (#dad444)', () => {
  test('New Lead: "350 5th Ave, New York" fills City = New York #dad444 @desktop @google-places', async ({ asUser }) => {
    const page = await asUser(ROLE);
    await openNewLead(page);

    await typeAndPickSuggestion(page, '350 5th Ave New York', '350 5th Ave', 'New York, NY, USA');

    await expect(zip(page)).toHaveValue('10118');
    await expect(addressInput(page)).toHaveValue('350 5th Ave, New York, NY 10118, USA');
    // коммент программиста #dad444 — в City город (для боро без города — боро)
    await expect(city(page)).toHaveValue('New York');
    await expect(region(page)).toHaveValue('New York');
  });
});
